// ----------------------------------------------------------------------------
// Primary Lookup Indexes and Query Functions
// ----------------------------------------------------------------------------
export const SACRED_AUDIO_REQUIREMENT_BY_ID: Record<string, SacredAudioRequirement> = Object.freeze(
  SACRED_AUDIO_MASTER_CATALOGUE.reduce<Record<string, SacredAudioRequirement>>((acc, req) => {
    acc[req.id] = req;
    return acc;
  }, {})
);

export function getRequirementById(id: string): SacredAudioRequirement | undefined {
  return SACRED_AUDIO_REQUIREMENT_BY_ID[id];
}

export function getRequirementsByTradition(tradition: TraditionId): readonly SacredAudioRequirement[] {
  return SACRED_AUDIO_MASTER_CATALOGUE.filter((req) => req.tradition === tradition);
}

export function getRequirementsByCohort(cohort: AudioRequirementCohort): readonly SacredAudioRequirement[] {
  return SACRED_AUDIO_MASTER_CATALOGUE.filter((req) => req.cohort === cohort);
}

export function getRequirementsByAvailability(availability: AudioAvailabilityState): readonly SacredAudioRequirement[] {
  return SACRED_AUDIO_MASTER_CATALOGUE.filter((req) => req.availability === availability);
}

export function getPlayableRequirements(): readonly SacredAudioRequirement[] {
  return SACRED_AUDIO_MASTER_CATALOGUE.filter((req) => req.isPlayable);
}

export function getBlockedRequirements(): readonly SacredAudioRequirement[] {
  return SACRED_AUDIO_MASTER_CATALOGUE.filter(
    (req) => req.cohort === 'LOCAL_PHYSICAL' && req.availability === 'AWAITING_PERMISSION'
  );
}

export function getAwaitingIntegrationRequirements(): readonly SacredAudioRequirement[] {
  return SACRED_AUDIO_MASTER_CATALOGUE.filter(
    (req) => req.cohort === 'ACCEPTED_YOUTUBE' && req.availability === 'AWAITING_APP_INTEGRATION'
  );
}

export function getSourceAvailablePermissionRequiredRequirements(): readonly SacredAudioRequirement[] {
  return SACRED_AUDIO_MASTER_CATALOGUE.filter(
    (req) => req.cohort === 'SOURCE_AVAILABLE_PERMISSION_REQUIRED'
  );
}

export function getPendingDiscoveryRequirements(): readonly SacredAudioRequirement[] {
  return SACRED_AUDIO_MASTER_CATALOGUE.filter(
    (req) => req.cohort === 'PENDING_DISCOVERY'
  );
}

export function getTextCardRequirements(): readonly SacredAudioRequirement[] {
  return SACRED_AUDIO_MASTER_CATALOGUE.filter((req) => req.cohort === 'TEXT_CARD');
}

