export function isApprovedPublicYouTubeId(id: string): boolean {
  return APPROVED_PUBLIC_YOUTUBE_IDS.has(id);
}

export function getApprovedYouTubeRequirements(): readonly SacredAudioRequirement[] {
  return SACRED_AUDIO_MASTER_CATALOGUE.filter(
    (req) => req.cohort === 'ACCEPTED_YOUTUBE' && isApprovedPublicYouTubeId(req.id)
  );
}

export function getPendingVerificationYouTubeRequirements(): readonly SacredAudioRequirement[] {
  return SACRED_AUDIO_MASTER_CATALOGUE.filter(
    (req) => req.cohort === 'ACCEPTED_YOUTUBE' && !isApprovedPublicYouTubeId(req.id)
  );
}

